package com.axion.mlbb.engine`n`nobject CounterBuildEngine {`n    fun recommendCounterItems(enemyRole: String, enemyDamageType: String): List<String> {`n        val recommendations = mutableListOf<String>()`n        if (enemyDamageType == "Physical") {`n            recommendations.add("Blade Armor")`n            recommendations.add("Dominance Ice")`n        } else if (enemyDamageType == "Magic") {`n            recommendations.add("Athena`'s Shield")`n            recommendations.add("Radiant Armor")`n        }`n        if (enemyRole == "Tank" || enemyRole == "Fighter") {`n            recommendations.add("Malefic Roar")`n        }`n        return recommendations`n    }`n}
